using System.Linq.Expressions;
using System.Reflection;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace Erupt;

/// <summary>
/// A declared erupt model, compiled into erupt build JSON. Nothing here re-implements annotation semantics: every
/// field and operation starts from the template the Java proxies emit (erupt-node-defaults.json, generated by
/// erupt-test NodeDefaultsTest); a declaration only overrides values on top of it.
/// </summary>
public partial class EruptModel
{
    public string Name { get; }

    public string Title { get; }

    internal Type ClrType { get; }

    internal List<FieldDef> Fields { get; } = [];

    internal Dictionary<string, FieldDef> FieldMap { get; } = [];

    /// <summary>The fields a repository keeps, in declaration order: every field but the virtual ones.</summary>
    internal IEnumerable<FieldDef> Stored => Fields.Where(f => !f.Virtual);

    /// <summary>The primary key field; null for a model that only serves as an operation form.</summary>
    internal string? Pk { get; }

    internal List<(string Field, bool Desc)> OrderBy { get; }

    /// <summary>View code -> the filters and order the node applies to that <c>@Vis</c> view's table queries.</summary>
    internal Dictionary<string, (List<SqlFilter> Filters, List<(string Field, bool Desc)> Sort)> Views { get; } = [];

    /// <summary>The reference field a <c>@LinkTree</c> filters the table by, and whether a tree node must be picked first.</summary>
    internal (string Field, bool DependNode)? LinkTree { get; private protected set; }

    internal JsonObject PowerJson { get; private protected set; } = Schema.Defaults["power"]!.DeepClone().AsObject();

    internal JsonObject Raw { get; } = [];

    internal List<OperationDef> Operations { get; } = [];

    [GeneratedRegex("^[A-Za-z_][A-Za-z0-9_]*$")]
    internal static partial Regex Identifier();

    [GeneratedRegex("(?<=[a-z0-9])([A-Z])|(?<=[A-Z])([A-Z][a-z])")]
    private static partial Regex WordBoundary();

    private protected EruptModel(Type type)
    {
        var attribute = type.GetCustomAttribute<EruptModelAttribute>()
                        ?? throw new ArgumentException($"{type.Name} is not marked with [EruptModel]");
        ClrType = type;
        Name = attribute.Name ?? type.Name;
        Title = attribute.Title;
        if (!Identifier().IsMatch(Name)) throw new ArgumentException($"erupt name '{Name}' must be an identifier");
        foreach (var property in Properties(type))
        {
            var field = FieldDef.From(this, property);
            if (field is null) continue;
            if (!FieldMap.TryAdd(field.Name, field)) throw new ArgumentException($"{Name}: field '{field.Name}' declared twice");
            Fields.Add(field);
        }
        var pks = Fields.Where(f => f.IsPk).ToList();
        if (pks.Count > 1) throw new ArgumentException($"{Name}: at most one [Pk]");
        Pk = pks.FirstOrDefault()?.Name;
        OrderBy = ParseOrder(attribute.OrderBy);
        Proxies = attribute.DataProxy.Select(t => typeof(IDataProxy).IsAssignableFrom(t)
            ? (IDataProxy)Activator.CreateInstance(t)!
            : throw new ArgumentException($"{Name}: DataProxy {t.Name} must implement IDataProxy")).ToList();
    }

    internal List<IDataProxy> Proxies { get; }

    /// <summary>Run one DataProxy hook on every proxy, in declaration order.</summary>
    internal void Hook(Action<IDataProxy> hook) => Proxies.ForEach(hook);

    /// <summary>The SQL every proxy's <see cref="IDataProxy.BeforeFetch"/> adds, in declaration order.</summary>
    internal List<SqlFilter> Filters(IReadOnlyList<Cond> conditions) =>
        Proxies.Select(p => p.BeforeFetch(conditions)).OfType<SqlFilter>().Where(f => f.Sql.Length > 0).ToList();

    /// <summary>Declare <typeparamref name="T"/>; the returned builder adds raw overrides and operations.</summary>
    public static EruptModel<T> Of<T>() => new();

    internal static IEnumerable<PropertyInfo> Properties(Type type) =>
        type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .OrderBy(p => p.DeclaringType == type ? 1 : 0) // inherited properties (a base Id) first
            .ThenBy(p => p.MetadataToken);

    /// <summary>The wire name of a property: explicit, else snake_case (<c>PublishDate</c> -> <c>publish_date</c>).</summary>
    internal static string? WireName(PropertyInfo property)
    {
        var pk = property.GetCustomAttribute<PkAttribute>();
        var field = property.GetCustomAttribute<FieldAttribute>();
        if (pk is null && field is null) return null;
        return pk?.Name ?? field?.Name ?? WordBoundary().Replace(property.Name, "_$1$2").ToLowerInvariant();
    }

    /// <summary><c>"views desc, id"</c> -> <c>[("views", true), ("id", false)]</c>, fields checked against the model.</summary>
    private protected List<(string, bool)> ParseOrder(string? orderBy)
    {
        var sort = new List<(string, bool)>();
        foreach (var part in (orderBy ?? "").Split(',').Select(p => p.Trim()).Where(p => p.Length > 0))
        {
            var words = part.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            var illegal = words.Length > 2 || !FieldMap.ContainsKey(words[0])
                          || (words.Length == 2 && words[1].ToLowerInvariant() is not ("asc" or "desc"));
            if (illegal) throw new ArgumentException($"{Name}: illegal OrderBy '{part}'");
            sort.Add((words[0], words.Length == 2 && words[1].Equals("desc", StringComparison.OrdinalIgnoreCase)));
        }
        return sort;
    }

    internal JsonObject BuildErupt(IEnumerable<OperationDef>? operations = null)
    {
        var json = Schema.Defaults["erupt"]!.DeepClone().AsObject();
        json["primaryKeyCol"] = Pk ?? "id";
        json["rowOperation"] = new JsonArray((operations ?? []).Select(o => (JsonNode)o.Build()).ToArray());
        Json.Merge(json, Raw);
        return new JsonObject
        {
            ["eruptName"] = Name,
            ["eruptJson"] = json,
            ["eruptFieldModels"] = new JsonArray(Fields.Select(f => (JsonNode)f.Build()).ToArray()),
            ["searchCondition"] = SearchCondition(),
            ["extraRow"] = false,
            ["tags"] = new JsonObject(),
        };
    }

    private JsonNode? SearchCondition()
    {
        var condition = new Record();
        Hook(p => p.SearchCondition(condition));
        return Values.ToJson(condition);
    }

    internal JsonObject BuildModel(JsonObject power, EruptUser? user)
    {
        var visible = Operations.Where(o => o.Visible(user)).ToList();
        var forms = new JsonObject();
        foreach (var op in visible.Where(o => o.Form is not null)) forms[op.Code] = op.Form!.BuildErupt();
        return new JsonObject
        {
            ["eruptModel"] = BuildErupt(visible),
            ["power"] = power.DeepClone(),
            ["tabErupts"] = null,
            ["combineErupts"] = null,
            ["operationErupts"] = forms.Count > 0 ? forms : null,
        };
    }

    internal static FieldDef Field(EruptModel model, string property) =>
        model.Fields.FirstOrDefault(f => f.Property.Name == property)
        ?? throw new ArgumentException($"{model.Name}: property {property} is not a [Field]");
}

/// <summary>Builder of a declared model: raw annotation overrides (typed and schema-checked) and row operations.</summary>
public sealed class EruptModel<T> : EruptModel
{
    internal EruptModel() : base(typeof(T))
    {
    }

    /// <summary>Raw <c>@Edit</c> attributes of a field, merged onto its template.</summary>
    public EruptModel<T> Edit<TProp>(Expression<Func<T, TProp>> property, Edit edit)
    {
        var f = Field(this, PropertyName(property));
        Json.Merge(f.EditRaw, Schema.Override("Edit", edit, $"{Name}.{f.Name}.edit"));
        return this;
    }

    /// <summary>Raw <c>@View</c> attributes of a field's table column.</summary>
    public EruptModel<T> View<TProp>(Expression<Func<T, TProp>> property, View view)
    {
        var f = Field(this, PropertyName(property));
        Json.Merge(f.ViewRaw, Schema.Override("View", view, $"{Name}.{f.Name}.view"));
        return this;
    }

    /// <summary>
    /// Raw <c>@Erupt</c> attributes (<c>new EruptOptions { Layout = new Layout { PageSize = 30 } }</c>). A <c>Vis</c>
    /// here replaces the views; declare a view with a filter or an order through <c>Vis(...)</c>.
    /// </summary>
    public EruptModel<T> Options(EruptOptions options)
    {
        Json.Merge(Raw, Schema.Override("Erupt", options, $"[EruptModel] {Name}"));
        if (Raw["linkTree"]?["field"]?.GetValue<string>() is { Length: > 0 } link)
        {
            if (!FieldMap.TryGetValue(link, out var f) || !f.IsReference)
                throw new ArgumentException($"{Name}: linkTree.field '{link}' must be a reference field");
            LinkTree = (link, Raw["linkTree"]?["dependNode"]?.GetValue<bool>() == true);
        }
        if (options.Vis is null) return this;
        Views.Clear();
        foreach (var entry in Raw["vis"]!.AsArray()) View(entry!.AsObject(), [], []);
        return this;
    }

    /// <summary>
    /// One <c>@Vis</c> view, appended to <c>vis</c>. <paramref name="filter"/> (SQL ANDed as written, SQL repositories
    /// only) and <paramref name="orderBy"/> (as <see cref="EruptModelAttribute.OrderBy"/>) are applied by the node when
    /// the table is read for this view and kept out of the build, as Java keeps them <c>@Transient</c>. A view
    /// without a <c>Code</c> is addressed by its title.
    /// </summary>
    public EruptModel<T> Vis(Vis vis, string? orderBy = null, params string[] filter)
    {
        var entry = Schema.Override("Vis", vis, $"[EruptModel] {Name}.vis");
        View(entry, [.. filter.Select(f => new SqlFilter(f))], ParseOrder(orderBy));
        ((Raw["vis"] ??= new JsonArray()) as JsonArray)!.Add(entry);
        return this;
    }

    private void View(JsonObject entry, List<SqlFilter> filters, List<(string, bool)> sort)
    {
        entry["code"] ??= entry["title"]?.DeepClone() ?? "";
        if (!Views.TryAdd(entry["code"]!.GetValue<string>(), (filters, sort)))
            throw new ArgumentException($"{Name}: vis code '{entry["code"]}' declared twice");
    }

    /// <summary>Switch features off; the server narrows them further per user.</summary>
    public EruptModel<T> Power(Power power)
    {
        Json.Merge(PowerJson, power.ToJson());
        return this;
    }

    /// <summary>
    /// A row operation. A non-empty returned string is run as JavaScript in the browser, so only return code you
    /// wrote; throw <see cref="EruptFailure"/> to show the user a message.
    /// </summary>
    public EruptModel<T> Operation(string code, OperationOptions options, Func<OperationContext, Task<string?>> handler)
    {
        if (string.IsNullOrEmpty(code)) throw new ArgumentException($"{Name}: an operation needs a code");
        if (Operations.Any(o => o.Code == code)) throw new ArgumentException($"{Name}: operation code '{code}' declared twice");
        Operations.Add(new OperationDef(code, options, handler, $"{Name}.{code}"));
        return this;
    }

    /// <summary>A row operation that returns no script.</summary>
    public EruptModel<T> Operation(string code, OperationOptions options, Func<OperationContext, Task> handler) =>
        Operation(code, options, async op =>
        {
            await handler(op);
            return null;
        });

    /// <summary>
    /// The options of a CHOICE / MULTI_CHOICE field, fetched with the form's values whenever the browser lists them.
    /// Throw <see cref="EruptFailure"/> to refuse with a message, here and in the field code below.
    /// </summary>
    public EruptModel<T> Fetch<TProp>(Expression<Func<T, TProp>> property, Func<Record, Task<IEnumerable<(string Value, string Label)>>> options) =>
        Invoke(property, "options", ["CHOICE", "MULTI_CHOICE"], async (form, _) =>
            new JsonArray([.. (await options(form)).Select(o => (JsonNode)new JsonObject { ["value"] = o.Value, ["label"] = o.Label })]));

    public EruptModel<T> Fetch<TProp>(Expression<Func<T, TProp>> property, Func<Record, IEnumerable<(string Value, string Label)>> options) =>
        Fetch(property, form => Task.FromResult(options(form)));

    /// <summary>The suggestions of a TAGS field, fetched with the form's values.</summary>
    public EruptModel<T> Fetch<TProp>(Expression<Func<T, TProp>> property, Func<Record, Task<IEnumerable<string>>> tags) =>
        Invoke(property, "options", ["TAGS"], async (form, _) => Values.ToJson(await tags(form)));

    public EruptModel<T> Fetch<TProp>(Expression<Func<T, TProp>> property, Func<Record, IEnumerable<string>> tags) =>
        Fetch(property, form => Task.FromResult(tags(form)));

    /// <summary>Run when the field changes in the form: values and expressions to apply to the form.</summary>
    public EruptModel<T> OnChange<TProp>(Expression<Func<T, TProp>> property, Func<Record, Task<FieldUpdate>> onchange) =>
        Invoke(property, "onchange", null, async (form, _) => (await onchange(form)).ToJson(button: false));

    public EruptModel<T> OnChange<TProp>(Expression<Func<T, TProp>> property, Func<Record, FieldUpdate> onchange) =>
        OnChange(property, form => Task.FromResult(onchange(form)));

    /// <summary>The suggestions of an AUTO_COMPLETE field for what the user typed.</summary>
    public EruptModel<T> Complete<TProp>(Expression<Func<T, TProp>> property, Func<Record, string, Task<IEnumerable<string>>> complete) =>
        Invoke(property, "autocomplete", ["AUTO_COMPLETE"], async (form, typed) => Values.ToJson(await complete(form, typed)));

    public EruptModel<T> Complete<TProp>(Expression<Func<T, TProp>> property, Func<Record, string, IEnumerable<string>> complete) =>
        Complete(property, (form, typed) => Task.FromResult(complete(form, typed)));

    /// <summary>Run when a BUTTON field is clicked.</summary>
    public EruptModel<T> Click<TProp>(Expression<Func<T, TProp>> property, Func<Record, Task<FieldUpdate>> click) =>
        Invoke(property, "button", ["BUTTON"], async (form, _) => (await click(form)).ToJson(button: true));

    public EruptModel<T> Click<TProp>(Expression<Func<T, TProp>> property, Func<Record, FieldUpdate> click) =>
        Click(property, form => Task.FromResult(click(form)));

    private EruptModel<T> Invoke<TProp>(Expression<Func<T, TProp>> property, string kind, string[]? types, Func<Record, string, Task<JsonNode?>> code)
    {
        var f = Field(this, PropertyName(property));
        if (f.IsPk || (types is not null && !types.Contains(f.Type)))
            throw new ArgumentException($"{Name}.{f.Name}: {kind} code belongs to {(types is null ? "a field" : string.Join(" / ", types))}, not {f.Type ?? "the primary key"}");
        f.Invoked[kind] = code;
        return this;
    }

    private string PropertyName<TProp>(Expression<Func<T, TProp>> property) =>
        (property.Body is UnaryExpression unary ? unary.Operand : property.Body) is MemberExpression member
            ? member.Member.Name
            : throw new ArgumentException($"{Name}: expected a property access like x => x.Title");
}

internal static class Json
{
    internal static JsonObject Merge(JsonObject target, JsonObject overrides)
    {
        foreach (var (key, value) in overrides)
        {
            if (value is JsonObject obj && target[key] is JsonObject existing) Merge(existing, obj);
            else target[key] = value?.DeepClone();
        }
        return target;
    }
}
